def count_up_to(n):
    """Return all prime numbers less than n."""
    primes = []
    for candidate in range(2, n):
        for prime in primes:
            if prime * prime > candidate:
                break
            if candidate % prime == 0:
                break
        else:
            primes.append(candidate)
            continue

        if prime * prime > candidate:
            primes.append(candidate)

    return primes
